import {WEAPONS,canControl,combatCosts} from './core/engine.js';
import {gridEntries,gridLayout,loadWeight} from './core/inventory.js';
import {characterArt} from './character-art.js';
import {inventoryArt} from './loot-art.js';
export const CHARACTER_STATS=[['strength','Strength'],['endurance','Endurance'],['dexterity','Dexterity'],['agility','Agility'],['intelligence','Intelligence'],['perception','Perception'],['mechanical','Mechanical'],['medical','Medical'],['firearms','Firearms'],['heavyWeapons','Heavy weapons'],['explosives','Explosives'],['leadership','Leadership'],['sneak','Sneak']];
const bounded=v=>Number.isFinite(v)?Math.max(1,Math.min(100,Math.round(v))):null;
export function characterSheet(u,{equipmentState='carried'}={}){
 const legacy={medical:u.medical,perception:u.perception,sneak:u.stealth},stats=CHARACTER_STATS.map(([key,label])=>({key,label,value:bounded(u.stats?.[key]??legacy[key])}));
 const equipment=(u.slots||[]).filter(Boolean).map(kind=>({type:kind==='wireCutters'?'utility':'weapon',kind,held:kind===u.weapon,stowed:kind===u.weapon&&equipmentState==='stowed',drawing:kind===u.weapon&&equipmentState==='drawing',rounds:u.ammo?.[kind]}));
 if(u.weapon==='hands')equipment.unshift({type:'weapon',kind:'hands',held:true});
 const layout=gridLayout(u),backpack=gridEntries(u).map(e=>({...e,cell:layout.entries.find(p=>p.key===e.key)?.cell}));
 return {name:u.name,species:u.species,portrait:characterArt(u.species,'hands').src,stats,equipment,backpack,weight:loadWeight(u),hp:u.hp,maxHp:u.maxHp,ap:u.ap,maxAp:u.maxAp,stamina:u.stamina,maxStamina:u.maxStamina};
}
const el=(tag,cls,text)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e;};
function itemCard(item){const name=WEAPONS[item.kind]?.name||({medkits:'Medical kit',wireCutters:'Wire cutters'}[item.kind])||item.kind,label=item.type==='ammo'?name+' ammunition':name,card=el('div','dossier-item'),src=inventoryArt(item);if(src){const image=el('img');image.src=src;image.alt='';card.append(image);}else card.append(el('span','item-symbol',item.kind==='hands'?'✊':'◆'));card.append(el('strong','',label));const details=item.held?(item.stowed?'Stowed':item.drawing?'Drawing':'In hand'):item.type==='ammo'||item.count?'Quantity: '+item.count:item.type==='weapon'&&WEAPONS[item.kind]?.mag?'Loaded: '+(item.rounds??0):'Ready';card.append(el('small','',details));if(item.held&&WEAPONS[item.kind]?.mag)card.append(el('small','','Loaded: '+(item.rounds??0)));return card;}
export function createCharacterScreen({getState,onOpen,onClose,getEquipmentState=()=> 'carried',onEquip,canEquip=()=>true}){
 const dialog=el('dialog','character-dossier');dialog.id='character-screen';dialog.setAttribute('aria-labelledby','character-name');document.body.append(dialog);let unitId;
 function render(){const state=getState(),roster=state.units.filter(u=>u.team==='squad'),u=roster.find(u=>u.id===unitId)||roster[0];if(!u)return;unitId=u.id;const sheet=characterSheet(u,{equipmentState:getEquipmentState(u.id)});dialog.replaceChildren();
  const top=el('div','dossier-top'),label=el('span','','Personnel / Field record'),close=el('button','','Close ×');close.id='character-close';close.onclick=()=>dialog.close();top.append(label,close);
  const nav=el('nav','dossier-roster');nav.setAttribute('aria-label','Squad character records');for(const merc of roster){const button=el('button','',merc.name);button.setAttribute('aria-pressed',String(merc.id===unitId));button.onclick=()=>{unitId=merc.id;render();dialog.querySelector('[aria-pressed="true"]').focus();};nav.append(button);}
  const body=el('div','dossier-body'),identity=el('section','dossier-identity'),portrait=el('img','dossier-portrait');portrait.src=sheet.portrait;portrait.alt=sheet.species+' sprite portrait';const name=el('h2','',sheet.name);name.id='character-name';identity.append(el('p','dossier-kicker','Animal Factory / Mercenary'),name,el('p','',sheet.species.replaceAll('-',' ')+' · '+(u.casualty||'Active')),portrait);
  const resources=el('dl','dossier-resources');for(const [key,value]of [['Health',sheet.hp+' / '+sheet.maxHp],['Action points',sheet.ap+' / '+sheet.maxAp],['Stamina',Number.isFinite(sheet.maxStamina)?(sheet.stamina??sheet.maxStamina)+' / '+sheet.maxStamina:'—']])resources.append(el('dt','',key),el('dd','',value));identity.append(resources);
  const stats=el('section','dossier-stats');stats.append(el('h3','','Attributes & skills'),el('p','dossier-kicker','Scale 1–100'));const list=el('dl','stat-list');for(const stat of sheet.stats){const row=el('div','stat-row');row.append(el('dt','',stat.label),el('dd','',stat.value??'—'));const meter=el('div','stat-meter');meter.style.setProperty('--stat',String(stat.value??0)+'%');meter.setAttribute('aria-hidden','true');row.append(meter);list.append(row);}stats.append(list);if(sheet.stats.some(s=>s.value===null)||!Number.isFinite(sheet.maxStamina))stats.append(el('p','dossier-note','— Not assigned yet. Health and AP show current battle values.'));
  const gear=el('section','dossier-gear');const equipmentCard=item=>{const card=itemCard(item);if(onEquip&&item.type==='weapon'&&!item.held&&item.kind!==u.weapon){const cost=combatCosts(state)&&!u.slots.includes(item.kind)?3:0,draw=el('button','draw-weapon','Draw'+(cost?' � '+cost+' AP':''));draw.dataset.weapon=item.kind;draw.disabled=!canControl(state,u)||!!state.queue.length||!canEquip(u)||u.ap<cost;draw.onclick=()=>{if(onEquip(u.id,item.kind))dialog.close();else render();};card.append(draw);}return card;};gear.append(el('h3','','Held & ready equipment'));const equipped=el('div','dossier-equipment');for(const item of sheet.equipment)equipped.append(equipmentCard(item));if(!sheet.equipment.length)equipped.append(el('p','','No equipment'));gear.append(equipped,el('h3','','Backpack'),el('p','dossier-kicker',sheet.weight.toFixed(1)+' kg carried · 18 backpack cells'));
  const pack=el('div','dossier-backpack');for(const entry of sheet.backpack){const card=equipmentCard(entry.item);card.dataset.itemKey=entry.key;card.style.gridColumn='span '+entry.span;pack.append(card);}if(!sheet.backpack.length)pack.append(el('p','','Backpack empty'));gear.append(pack);body.append(identity,stats,gear);dialog.append(top,nav,body);
 }
 dialog.addEventListener('close',()=>onClose?.());return {get open(){return dialog.open;},show(id){unitId=id;render();dialog.showModal();onOpen?.();dialog.querySelector('#character-close').focus();}};
}
